function preparePost({ siteId, title, content, status }) {
  if (typeof siteId !== "string" || !/^[1-9]\d{0,19}$/.test(siteId)) {
    throw new Error("Set the numeric WordPress.com site ID");
  }
  if (
    typeof title !== "string" ||
    !title.trim() ||
    typeof content !== "string" ||
    !content.trim()
  ) {
    throw new Error("Enter a post title and body");
  }
  if (status !== "draft" && status !== "publish") {
    throw new Error("Choose draft or publish for the post status");
  }
  return {
    url: "https://public-api.wordpress.com/wp/v2/sites/" + siteId + "/posts?_fields=id,status,type",
    payload: { title, content, status },
    requestedStatus: status,
  };
}
const settings = {
  siteId: "YOUR_WORDPRESS_COM_SITE_ID",
  title: "A sample article",
  content: "<p>Write your article here. You can include <strong>HTML formatting</strong>.</p>",
  status: "draft",
};
return [{ json: preparePost(settings) }];

function confirmPost({ statusCode, response, expectedStatus }) {
  if (statusCode >= 400 && statusCode < 500 && statusCode !== 408) {
    throw new Error("WordPress.com rejected the post request (HTTP " + statusCode + ")");
  }
  const unknown = "WordPress.com did not confirm creation. Check the site before retrying";
  if (statusCode !== 201) throw new Error(unknown + " (HTTP " + statusCode + ")");
  let post;
  try {
    post = JSON.parse(response);
  } catch {
    throw new Error(unknown);
  }
  if (
    !Number.isSafeInteger(post?.id) ||
    post.id < 1 ||
    post.type !== "post" ||
    post.status !== expectedStatus
  ) {
    throw new Error(unknown);
  }
  return { postId: post.id, status: post.status };
}
const { statusCode, data: response } = $input.first().json;
const expectedStatus = $("Set site and article").first().json.payload.status;
return [{ json: confirmPost({ statusCode, response, expectedStatus }) }];
